INSERT OR IGNORE INTO questions
(id,track_id,topic,difficulty,question_type,prompt,options_json,answer_json,explanation,source_type,source_reference,language)
VALUES
('sg-official-h28h-2016-q01','exam-sg','CSIRT・インシデント対応','standard','single_choice','【2016年度 平成28年春期 午前 問1】CSIRTの説明として，適切なものはどれか。','[{"id":"a","text":"IPアドレスの割当て方針やDNSルートサーバの運用を世界規模で行う組織"},{"id":"b","text":"インターネット技術文書を作成し，標準化の検討を行う組織"},{"id":"c","text":"組織内などに設置され，セキュリティインシデントの報告を受け，調査・対応する組織"},{"id":"d","text":"情報技術を利用して宗教的・政治的な目標を達成しようとする人や組織"}]','"c"','正解はウ。CSIRTは組織のセキュリティインシデントを受け付け，調査・対応するチームである。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000gn5o-att/2016h28h_sg_am_qs.pdf','ja'),
('sg-official-h28h-2016-q02','exam-sg','物理的セキュリティ・クリアデスク','standard','single_choice','【2016年度 平成28年春期 午前 問2】情報セキュリティ対策のクリアデスクに該当するものはどれか。','[{"id":"a","text":"PCのデスクトップ上のフォルダを整理する。"},{"id":"b","text":"離席時に一定時間でパスワード付き画面ロックへ切り替える。"},{"id":"c","text":"帰宅時に書類やノートPCを机上に放置せず，施錠できる引出しなどに保管する。"},{"id":"d","text":"机上のノートPCをセキュリティワイヤで固定する。"}]','"c"','正解はウ。クリアデスクは，離席・退勤時に書類や機器を机上に放置せず，適切に保管する対策である。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000gn5o-att/2016h28h_sg_am_qs.pdf','ja'),
('sg-official-h28h-2016-q03','exam-sg','情報セキュリティ監査','standard','single_choice','【2016年度 平成28年春期 午前 問3】リスクアセスメントに基づくコントロールの整備・運用状況を独立かつ専門的な立場から検証・評価し，保証又は助言を与えるものはどれか。','[{"id":"a","text":"コントロールセルフアセスメント（CSA）"},{"id":"b","text":"情報セキュリティ監査"},{"id":"c","text":"情報セキュリティ対策ベンチマーク"},{"id":"d","text":"デジタルフォレンジックス"}]','"b"','正解はイ。情報セキュリティ監査は独立した立場で対策の整備・運用状況を検証し，保証や助言を行う。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000gn5o-att/2016h28h_sg_am_qs.pdf','ja'),
('sg-official-h28h-2016-q04','exam-sg','モバイル端末・紛失対策','standard','single_choice','【2016年度 平成28年春期 午前 問4】重要情報を格納したノートPCやスマートフォンなどの紛失による情報漏えい対策として有効なものはどれか。','[{"id":"a","text":"モバイル機器でのSNS使用を制限する。"},{"id":"b","text":"機器内の情報をリモートから消去できるツールを導入する。"},{"id":"c","text":"機器に通信を暗号化するツールを導入する。"},{"id":"d","text":"機器にのぞき見防止フィルムを貼る。"}]','"b"','正解はイ。紛失時に遠隔消去できるようにすると，端末内に残った情報が漏えいするリスクを低減できる。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000gn5o-att/2016h28h_sg_am_qs.pdf','ja'),
('sg-official-h28h-2016-q05','exam-sg','リスク受容・ISMS','standard','single_choice','【2016年度 平成28年春期 午前 問5】JIS Q 27001において，リスクを受容するプロセスに求められるものはどれか。','[{"id":"a","text":"受容するリスクについて，リスク所有者が承認する。"},{"id":"b","text":"受容するリスクをモニタリングやレビューの対象外とする。"},{"id":"c","text":"リスク分析を行う前にリスクを受容する。"},{"id":"d","text":"リスク対応後に限って受容可否を決定する。"}]','"a"','正解はア。リスク受容にはリスク所有者の承認が必要であり，受容後も状況の変化を監視する。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000gn5o-att/2016h28h_sg_am_qs.pdf','ja'),
('sg-official-h28h-2016-q06','exam-sg','情報セキュリティ方針','standard','single_choice','【2016年度 平成28年春期 午前 問6】JIS Q 27001に基づく情報セキュリティ方針の取扱いとして，適切なものはどれか。','[{"id":"a","text":"機密情報として厳格に管理する。"},{"id":"b","text":"従業員及び関連する外部関係者に通知する。"},{"id":"c","text":"情報セキュリティ担当者が各自で作成する。"},{"id":"d","text":"制定後は見直さずに済む内容で作成する。"}]','"b"','正解はイ。情報セキュリティ方針は関係する従業員や外部関係者に伝達し，理解される必要がある。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000gn5o-att/2016h28h_sg_am_qs.pdf','ja'),
('sg-official-h28h-2016-q07','exam-sg','内部不正防止・Webアクセス管理','standard','single_choice','【2016年度 平成28年春期 午前 問7】IPA「組織における内部不正防止ガイドライン」にも記載されている，組織の適切な情報セキュリティ対策はどれか。','[{"id":"a","text":"Webサイトへのアクセスにコンテンツフィルタを導入し，SNSやオンラインストレージ等へのアクセスを制限する。"},{"id":"b","text":"業務メールを障害に備えて私用メールアドレスへ自動転送する。"},{"id":"c","text":"ファイル共有ソフト利用時はウイルス対策ソフトを一時的に無効にする。"},{"id":"d","text":"許可されていないソフトウェアも，業務効率が上がるなら従業員の判断で導入させる。"}]','"a"','正解はア。組織のルールに基づいてWebアクセスを制御し，不正な情報持出しや危険なサイトへの接続を抑制する。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000gn5o-att/2016h28h_sg_am_qs.pdf','ja'),
('sg-official-h28h-2016-q08','exam-sg','特権アクセス管理','standard','single_choice','【2016年度 平成28年春期 午前 問8】情報システムに対するアクセスのうち，JIS Q 27002でいう特権的アクセス権を利用した行為はどれか。','[{"id":"a","text":"営業担当者が社外から営業システムにアクセスして業務を行う。"},{"id":"b","text":"経営者が機密性の高い経営情報を閲覧する。"},{"id":"c","text":"システム管理者が業務システムのプログラムをバージョンアップする。"},{"id":"d","text":"来訪者がデモシステムにアクセスして機能を確認する。"}]','"c"','正解はウ。システム管理者がプログラム更新など管理権限を必要とする操作を行うことは，特権アクセスの利用に当たる。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000gn5o-att/2016h28h_sg_am_qs.pdf','ja'),
('sg-official-h28h-2016-q09','exam-sg','内部統制・不正のトライアングル','standard','single_choice','【2016年度 平成28年春期 午前 問9】「不正のトライアングル」理論において，全てそろったときに不正が発生すると考えられている3要素はどれか。','[{"id":"a","text":"機会，動機，正当化"},{"id":"b","text":"顧客，競合，自社"},{"id":"c","text":"機密性，完全性，可用性"},{"id":"d","text":"認証，認可，アカウンティング"}]','"a"','正解はア。不正のトライアングルは，動機・機会・正当化の三要素で構成される。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000gn5o-att/2016h28h_sg_am_qs.pdf','ja'),
('sg-official-h28h-2016-q10','exam-sg','ログ管理・内部不正検知','standard','single_choice','【2016年度 平成28年春期 午前 問10】利用者アクセスログの取扱いのうち，内部不正の早期発見及び事後対策の観点で適切なものはどれか。','[{"id":"a","text":"コストにかかわらずログを永久保存する。"},{"id":"b","text":"利用者にログの管理権限を付与する。"},{"id":"c","text":"利用者にログの保存期間を周知することだけを行う。"},{"id":"d","text":"ログを定期的に確認する。"}]','"d"','正解はエ。アクセスログを定期的に確認することで，不自然なアクセスや内部不正の兆候を早期に発見できる。','official','https://www.ipa.go.jp/shiken/mondai-kaiotu/gmcbt8000000gn5o-att/2016h28h_sg_am_qs.pdf','ja');
